import {
  Drawer,
  DrawerBody,
  DrawerHeader,
  DrawerOverlay,
  DrawerContent,
  DrawerCloseButton,
  useDisclosure,
  Button,
  useColorMode,
} from "@chakra-ui/react";
import "./sideDrawer.css";
import React from "react";
import { Link } from "react-scroll";
import { RxHamburgerMenu } from "react-icons/rx";
import { MoonIcon, SunIcon } from "@chakra-ui/icons";

function SideDrawer() {
  const { isOpen, onOpen, onClose } = useDisclosure();
  const { colorMode, toggleColorMode } = useColorMode();
  const btnRef = React.useRef();
  const onButtonClick = () => {
    window.open(
      "https://drive.google.com/drive/folders/1TsbwJmRsPcUFmxwpEfMWPmTQkld1qtoo"
    );
  };

  return (
    <>
      <Button ref={btnRef} onClick={onOpen}>
        <RxHamburgerMenu size="30" />
      </Button>
      <Drawer
        isOpen={isOpen}
        placement="right"
        onClose={onClose}
        finalFocusRef={btnRef}
      >
        <DrawerOverlay />
        <DrawerContent>
          <DrawerCloseButton />
          <DrawerHeader>
            <img
              src="https://i.pinimg.com/474x/4d/35/c1/4d35c148dc6c150ee912b90f4c25e953.jpg"
              alt="ranjan"
              style={{ width: "20%", marginBottom: "0px" }}
            />
            <hr />
          </DrawerHeader>

          <DrawerBody>
            <div className="body-drawer-section">
              <Link to="home" smooth={true} duration={1000} onClick={onClose}>
                Home
              </Link>
            </div>
            <div className="body-drawer-section">
              <Link to="about" smooth={true} duration={1000} onClick={onClose}>
                About
              </Link>
            </div>
            <div className="body-drawer-section">
              <Link to="skill" smooth={true} duration={1000} onClick={onClose}>
                Skills
              </Link>
            </div>
            <div className="body-drawer-section">
              <Link
                to="project"
                smooth={true}
                duration={1000}
                onClick={onClose}
              >
                Project
              </Link>
            </div>
            <div className="body-drawer-section">
              <Link
                to="contact"
                smooth={true}
                duration={1000}
                onClick={onClose}
              >
                Contact
              </Link>
            </div>
            <div className="body-drawer-section">
              <a
                href="Ranjan_Kumar_Resume.pdf"
                target="_blank"
                download
                onClick={onButtonClick}
              >
                Resume
              </a>
            </div>
            <div className="body-drawer-section">
              <Button onClick={toggleColorMode} className="colormode2">
                {colorMode === "light" ? <MoonIcon /> : <SunIcon />}
              </Button>
            </div>

            {/* <p>Home</p>
              <p>About</p>
              <p>Skills</p>
              <p>Project</p>
              <p>Contact</p>
              <p>Resume</p> */}
          </DrawerBody>

          {/* <DrawerFooter>
              
            </DrawerFooter> */}
        </DrawerContent>
      </Drawer>
    </>
  );
}
export default SideDrawer;
