import React from "react";
import "./Navbar1.css";
import { Link } from "react-scroll";
import SideDrawer from "./SideDraw";
import { useColorMode, Button } from "@chakra-ui/react";
import { MoonIcon, SunIcon } from "@chakra-ui/icons";

const Navbar1 = () => {
  const { colorMode, toggleColorMode } = useColorMode();

  const onButtonClick = () => {
    window.open(
      "https://drive.google.com/drive/folders/1TsbwJmRsPcUFmxwpEfMWPmTQkld1qtoo"
    );
  };

  const navStyle = {
    backgroundColor: colorMode === "light" ? "white" : "black",
    color: colorMode === "light" ? "black" : "white",
  };

  const buttonStyle = {
    color: "black",
  };

  return (
    <div className="nav" style={navStyle}>
      <Link to="home" smooth={true} duration={1000}>
        <div className="nav1">
          <img
            className="ranjan-logo"
            src="https://i.pinimg.com/474x/4d/35/c1/4d35c148dc6c150ee912b90f4c25e953.jpg"
            alt="ranjan"
          />
        </div>
      </Link>
      <div className="nav2">
        <Link to="home" smooth={true} duration={1000}>
          <button style={buttonStyle}>Home</button>
        </Link>

        <Link to="about" smooth={true} duration={1000}>
          <button style={buttonStyle}>About</button>
        </Link>

        <Link to="skill" smooth={true} duration={1000}>
          <button style={buttonStyle}>Skill</button>
        </Link>

        <Link to="project" smooth={true} duration={1000}>
          <button style={buttonStyle}>Project</button>
        </Link>
        <Link to="contact" smooth={true} duration={1000}>
          <button style={buttonStyle}>Contact</button>
        </Link>
        <a href="Ranjan_Kumar_Resume.pdf" download>
          <button onClick={onButtonClick} style={buttonStyle}>
            Resume
          </button>
        </a>
        <p onClick={toggleColorMode} className="colormode">
          {colorMode === "light" ? <MoonIcon /> : <SunIcon />}
        </p>
      </div>
      <div className="nav3">
        <SideDrawer />
      </div>
    </div>
  );
};

export default Navbar1;
