import React, { useEffect } from "react";
import "./Home.css";
import image from './Ranjan_img.jfif'
import Aos from "aos";

const Home = () => {

  const onButtonClick = () => {
    window.open('https://drive.google.com/drive/folders/1TsbwJmRsPcUFmxwpEfMWPmTQkld1qtoo')
}
useEffect(()=> {
  Aos.init({
    duration: 3000,
    // easing: 'ease-in-out',
  });
})

  return (
    <div name="home" className="header">
      <div className="header2">
        <img
          src={image}
          alt="image"
        />
      </div>
      <div className="header1">
        <div className="head1" data-aos="fade-up">
          <h2>Hey, my name is</h2>
        </div>
        <div className="head2"  data-aos="fade-up">
          <h1>Ranjan Kumar</h1>
        </div>
        <div className="head3"  data-aos="fade-up">
          <h3>I am a full stack web developer</h3>
        </div>
        <div className="head5"  data-aos="fade-up">
          
          <a href="Ranjan_Kumar_Resume.pdf" target="_blank" download>
            <button onClick={onButtonClick}>
              Resume
            </button>
          </a>
        
        </div>
      </div>
    </div>
  );
};

export default Home;
